pub(crate) fn collect_object_closure(
    store: &ObjectStore,
    roots: &[String],
) -> Result<Vec<ObjectBundleObject>> {
    let mut cids = BTreeSet::new();
    let mut pending = roots.to_vec();
    for root in roots {
        cids.insert(root.clone());
    }
    while let Some(cid) = pending.pop() {
        let canonical = object_bytes(store, &cid)?;
        match decode_node(&canonical)? {
            Node::Corpus(entries) => {
                for entry in entries {
                    if cids.insert(entry.cid.clone()) {
                        pending.push(entry.cid);
                    }
                }
            }
            Node::Value(value) => push_value_refs(&value, &mut cids, &mut pending),
            Node::Text(_) => {}
        }
    }
    cids.into_iter()
        .map(|cid| object_entry(store, &cid))
        .collect()
}

fn push_value_refs(value: &Value, cids: &mut BTreeSet<String>, pending: &mut Vec<String>) {
    let mut refs = Vec::new();
    collect_value_refs(value, &mut refs);
    for reference in refs {
        if cids.insert(reference.clone()) {
            pending.push(reference);
        }
    }
}

fn object_entry(store: &ObjectStore, cid: &str) -> Result<ObjectBundleObject> {
    let canonical = object_bytes(store, cid)?;
    let node = decode_node(&canonical)?;
