pub(crate) fn connect(address: &str) -> Result<TcpStream> {
    let addresses = address
        .to_socket_addrs()
        .with_context(|| format!("failed to resolve peer address {address}"))?;
    let mut last_error = None;
    for socket in addresses {
        for _ in 0..20 {
            match TcpStream::connect_timeout(&socket, Duration::from_millis(250)) {
                Ok(stream) => return Ok(stream),
                Err(error) => {
                    last_error = Some(error);
                    std::thread::sleep(Duration::from_millis(25));
                }
            }
        }
    }
    Err(last_error
        .map(anyhow::Error::from)
        .unwrap_or_else(|| anyhow::anyhow!("peer address resolved to no sockets")))
    .with_context(|| format!("failed to connect to peer {address}"))
}

pub(crate) fn configure_stream(stream: &TcpStream) -> Result<()> {
    stream.set_read_timeout(Some(IO_TIMEOUT))?;
    stream.set_write_timeout(Some(IO_TIMEOUT))?;
    Ok(())
}

pub(crate) fn validate_node_id(node: &str) -> Result<()> {
    if node.is_empty()
        || node.len() > 64
        || !node
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'.' | b'_' | b'-'))
    {
        bail!("peer node identity must use 1-64 ASCII letters, digits, '.', '_' or '-'");
    }
    Ok(())
}

fn emit<T: Serialize>(output: &T, format: OutputFormat) -> Result<()> {
    match format {
        OutputFormat::Json => print_json(output),
        OutputFormat::Text => {
            println!("{}", serde_json::to_string(output)?);
            Ok(())
        }
    }
}

